/// SQLite-backed persistence for GPU metrics history.
use chrono::{DateTime, Utc};
use rusqlite::{Connection, Params, Result as SqlResult};
use std::sync::Mutex;
use tracing::{debug, info, warn};

// ── Domain types ──────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct GpuRecord {
    pub timestamp: DateTime<Utc>,
    pub memory_used_mib: Option<u64>,
    pub temperature_c: Option<f64>,
}

// ── Database wrapper ──────────────────────────────────────────

pub struct Database {
    conn: Mutex<Connection>,
}

impl Database {
    /// Open (or create) the SQLite file at the given path, ensuring schema exists.
    pub fn new(path: &str) -> Self {
        let conn = Connection::open(path).unwrap_or_else(|e| {
            warn!("Failed to open sqlite db at {}: {}, using in-memory fallback", path, e);
            Connection::open_in_memory().expect("in-memory db should always work")
        });

        Self::ensure_schema(&conn).ok();
        Self {
            conn: Mutex::new(conn),
        }
    }

    fn ensure_schema(conn: &Connection) -> SqlResult<()> {
        conn.execute_batch(
            "
            CREATE TABLE IF NOT EXISTS gpu_history (
                id         INTEGER PRIMARY KEY AUTOINCREMENT,
                ts_epoch   INTEGER NOT NULL,
                memory_used_mib  INTEGER,
                temperature_c    REAL
            );
            CREATE INDEX IF NOT EXISTS idx_gpu_ts ON gpu_history(ts_epoch);
            ",
        )?;
        Ok(())
    }

    /// Insert a single GPU snapshot.
    pub fn insert(&self, mem_used: Option<u64>, temp: Option<f64>) {
        let conn = self.conn.lock().unwrap();
        let epoch = Utc::now().timestamp_millis();
        match conn.execute(
            "INSERT INTO gpu_history (ts_epoch, memory_used_mib, temperature_c) VALUES (?1, ?2, ?3)",
            (epoch as i64, mem_used as Option<i64>, temp),
        ) {
            Ok(_) => debug!("Inserted GPU record at {}", epoch),
            Err(e) => warn!("Failed to insert GPU record: {}", e),
        }
    }

    /// Fetch records within the last `duration_secs` seconds.
    pub fn fetch_history(&self, duration_secs: u64) -> Vec<GpuRecord> {
        let conn = self.conn.lock().unwrap();
        let cutoff = Utc::now().timestamp_millis() - (duration_secs as i128 * 1000);

        let mut stmt = conn.prepare(
            "SELECT ts_epoch, memory_used_mib, temperature_c \
             FROM gpu_history \
             WHERE ts_epoch >= ?1 \
             ORDER BY ts_epoch ASC"
        ).unwrap_or_else(|e| {
            warn!("Failed to prepare history query: {}", e);
            unreachable!()
        });

        let rows = stmt.query_map([cutoff as i64], |row| {
            Ok(GpuRecord {
                timestamp: DateTime::from_timestamp_millis(row.get(0)?).unwrap_or_default(),
                memory_used_mib: row.get::<_, Option<i64>>(1)?.map(|v| v as u64),
                temperature_c: row.get(2).ok(),
            })
        }).unwrap_or_else(|e| {
            warn!("Failed to query history: {}", e);
            unreachable!()
        });

        rows.filter_map(|r| r.ok()).collect()
    }

    /// Return the all-time maximum VRAM usage (in MiB).
    pub fn peak_vram(&self) -> Option<u64> {
        let conn = self.conn.lock().unwrap();
        conn.query_row(
            "SELECT MAX(memory_used_mib) FROM gpu_history WHERE memory_used_mib IS NOT NULL",
            [],
            |row| row.get::<_, Option<i64>>(0).map(|v| v as u64),
        ).unwrap_or(None)
    }

    /// Delete all rows from the history table.
    pub fn clear_history(&self) {
        let conn = self.conn.lock().unwrap();
        match conn.execute("DELETE FROM gpu_history", []) {
            Ok(n) => info!("Cleared {} GPU history records", n),
            Err(e) => warn!("Failed to clear GPU history: {}", e),
        }
    }
}

/// Shared data types for Ollama and GPU state.
use serde::{Deserialize, Serialize};

// ── Ollama API response types ───────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OllamaTagsResponse {
    pub models: Vec<OllamaModelEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OllamaModelEntry {
    #[serde(rename = "name")]
    pub model_name: String,
    #[serde(rename = "size")]
    pub size_bytes: Option<u64>,
    #[serde(rename = "digest")]
    pub digest: Option<String>,
    #[serde(rename = "modified_at")]
    pub modified_at: Option<String>,
}

// ── Aggregated status (exposed by REST API) ─────────────────────

#[derive(Debug, Clone, Serialize)]
pub struct MonitorStatus {
    pub ollama_url: String,
    pub ollama_reachable: bool,
    pub loaded_model: Option<String>,
    pub available_models: Vec<String>,
    pub gpu: GpuMetric,
    pub timestamp: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct GpuMetric {
    pub name: Option<String>,
    pub temperature_c: Option<f64>,
    pub memory_used_mib: Option<u64>,
    pub memory_total_mib: Option<u64>,
    pub memory_remaining_mib: Option<u64>,
    pub utilization_pct: Option<f64>,
    pub power_watts: Option<f64>,
}

impl GpuMetric {
    pub fn placeholder() -> Self {
        Self {
            name: None,
            temperature_c: None,
            memory_used_mib: None,
            memory_total_mib: None,
            memory_remaining_mib: None,
            utilization_pct: None,
            power_watts: None,
        }
    }
}

// ── Web API response types (subset views) ──────────────────────

#[derive(Debug, Clone, Serialize)]
pub struct ApiModelResponse {
    pub loaded_model: Option<String>,
    pub available_models: Vec<String>,
    pub total_count: usize,
}

#[derive(Debug, Clone, Serialize)]
pub struct ApiGpuResponse {
    pub gpu: GpuMetric,
    pub timestamp: String,
}

// ── History API response types ─────────────────────────────────

#[derive(Debug, Clone, Serialize)]
pub struct GpuHistoryPoint {
    pub timestamp: u64,
    pub memory_used_mib: Option<u64>,
    pub temperature_c: Option<f64>,
}

#[derive(Debug, Clone, Serialize)]
pub struct GpuHistoryResponse {
    pub data: Vec<GpuHistoryPoint>,
    pub peak_vram_mib: Option<u64>,
}

/// Application-wide configuration loaded from environment variables with sensible defaults.
///
/// Environment variables:
///
/// | Variable                  | Default               | Description                                |
/// |---------------------------|-----------------------|--------------------------------------------|
/// | `OLLAMA_HOST`             | `http://127.0.0.1`      | Ollama server base URL                     |
/// | `OLLAMA_PORT`             | `11434`               | Ollama server port                         |
/// | `SERVER_BIND`             | `0.0.0.0`             | Address to bind the API server to          |
/// | `SERVER_PORT`             | `3000`                | Port for the API server                    |
/// | `REFRESH_INTERVAL_SECS`   | `15`                  | Seconds between status refreshes           |
/// | `GPU_DEVICE_INDEX`        | `0`                   | NVIDIA GPU device index to query           |
/// | `DB_PATH`                 | `.ollama_monitor.db`  | SQLite database path for history data      |

#[derive(Debug, Clone)]
pub struct Config {
    pub ollama_host: String,
    pub ollama_port: u16,
    pub server_bind: String,
    pub server_port: u16,
    pub refresh_interval_secs: u64,
    pub gpu_device_index: usize,
    pub db_path: String,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            ollama_host: "http://127.0.0.1".into(),
            ollama_port: 11434,
            server_bind: "0.0.0.0".into(),
            server_port: 3000,
            refresh_interval_secs: 15,
            gpu_device_index: 0,
            db_path: ".ollama_monitor.db".into(),
        }
    }
}

impl Config {
    /// Load config from environment variables, falling back to defaults for unset values.
    pub fn load() -> Self {
        let mut config = Self::default();

        if let Ok(val) = std::env::var("OLLAMA_HOST") {
            config.ollama_host = val;
        }
        if let Ok(val) = std::env::var("OLLAMA_PORT") {
            if let Ok(port) = val.parse::<u16>() {
                config.ollama_port = port;
            } else {
                tracing::warn!("Invalid OLLAMA_PORT '{}', using default", val);
            }
        }

        if let Ok(val) = std::env::var("SERVER_BIND") {
            config.server_bind = val;
        }
        if let Ok(val) = std::env::var("SERVER_PORT") {
            if let Ok(port) = val.parse::<u16>() {
                config.server_port = port;
            } else {
                tracing::warn!("Invalid SERVER_PORT '{}', using default", val);
            }
        }
        if let Ok(val) = std::env::var("REFRESH_INTERVAL_SECS") {
            if let Ok(interval) = val.parse::<u64>() {
                config.refresh_interval_secs = interval;
            } else {
                tracing::warn!("Invalid REFRESH_INTERVAL_SECS '{}', using default", val);
            }
        }

        if let Ok(val) = std::env::var("GPU_DEVICE_INDEX") {
            if let Ok(index) = val.parse::<usize>() {
                config.gpu_device_index = index;
            } else {
                tracing::warn!("Invalid GPU_DEVICE_INDEX '{}', using default", val);
            }
        }

        if let Ok(val) = std::env::var("DB_PATH") {
            config.db_path = val;
        }

        config
    }

    pub fn ollama_base_url(&self) -> String {
        format!("{}:{}", self.ollama_host, self.ollama_port)
    }
}

/// Ollama Monitor — main entry point.
mod api;
mod config;
mod db;
mod gpu;
mod models;
mod ollama;

use anyhow::Result;
use tracing_subscriber::{fmt, EnvFilter};

#[tokio::main]
async fn main() -> Result<()> {
    let env_filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));
    fmt::Subscriber::builder()
        .with_env_filter(env_filter)
        .init();

    let config = config::Config::load();
    tracing::info!(?config, "Configuration loaded");

    let database = db::Database::new(&config.db_path);
    let state = api::AppState::new(database);

    let cfg_clone = config.clone();
    let state_clone = state.clone();
    tokio::spawn(async move {
        api::run_refresh_loop(&cfg_clone, state_clone).await;
    });

    let addr = api::bind_listener(&config).await?;
    let app = api::build_router(state);

    tracing::info!("Starting Ollama Monitor on {:?}/api/status", addr);
    let listener = tokio::net::TcpListener::bind(&addr).await?;
    Ok(axum::serve(listener, app).await?)
}

