/// Axum REST API server + embedded web dashboard.

use anyhow::Result;
use axum::{
    body::Body,
    extract::State,
    extract::Query,
    http::{header, Request, StatusCode},
    response::Html,
    routing::{get, post},
    Json, Router,
};
use chrono::Utc;
use std::{net::SocketAddr, sync::Arc, time::Duration};
use tokio::sync::RwLock;
use tracing::info as log_info;

use crate::config::Config;
use crate::db::Database;
use crate::gpu::try_query_gpu;
use crate::models::{
    ApiGpuResponse, ApiModelResponse, GpuHistoryPoint, GpuHistoryResponse, MonitorStatus,
};
use crate::ollama::OllamaClient;

fn now_ts() -> String {
    use std::time::SystemTime;
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .map_or("unknown".into(), |d| {
            let s = d.as_secs();
            format!("{} days {:02}:{:02}", s / 86400, (s % 3600) / 60, s % 60)
        })
}

#[derive(Clone)]
pub struct AppState {
    pub latest_status: Arc<RwLock<Option<MonitorStatus>>>,
    pub database: Database,
}

impl AppState {
    pub fn new(database: Database) -> Self {
        Self {
            latest_status: Arc::new(RwLock::new(None)),
            database,
        }
    }
}

// ── Background refresh loop ──────────────────────────────

pub async fn run_refresh_loop(config: &Config, state: AppState) {
    let client = OllamaClient::new(config.ollama_base_url());
    let interval = Duration::from_secs(config.refresh_interval_secs);

    loop {
        tokio::time::sleep(interval).await;

        let tags_resp = client.try_fetch_models().await;
        let available: Vec<String> = match &tags_resp {
            Some(tags) => tags.models.iter().map(|m| m.model_name.clone()).collect(),
            None => vec![],
        };
        let loaded_model = tags_resp
            .as_ref()
            .and_then(|t| t.models.first().cloned().map(|m| m.model_name));

        let gpu_metric = try_query_gpu(config.gpu_device_index);

        // Persist GPU snapshot to SQLite each cycle
        state
            .database
            .insert(gpu_metric.memory_used_mib, gpu_metric.temperature_c);

        let status = MonitorStatus {
            ollama_url: config.ollama_base_url(),
            ollama_reachable: tags_resp.is_some(),
            loaded_model,
            available_models: available.clone(),
            gpu: gpu_metric,
            timestamp: now_ts(),
        };

        let mut latest = state.latest_status.write().await;
        *latest = Some(status);
    }
}

// ── HTTP Handlers ────────────────────────────────────────

async fn handle_dashboard() -> Html<&'static str> {
    Html(DASHBOARD_HTML)
}

async fn handle_api_status(
    State(state): State<AppState>,
) -> Result<Json<MonitorStatus>, (StatusCode, String)> {
    let latest = state.latest_status.read().await;
    match latest.as_ref() {
        Some(s) => Ok(Json(s.clone())),
        None => Err((
            StatusCode::SERVICE_UNAVAILABLE,
            "First refresh not yet complete".into(),
        )),
    }
}

async fn handle_api_gpu(
    State(state): State<AppState>,
) -> Result<Json<ApiGpuResponse>, (StatusCode, String)> {
    let latest = state.latest_status.read().await;
    match latest.as_ref() {
        Some(s) => Ok(Json(ApiGpuResponse {
            gpu: s.gpu.clone(),
            timestamp: s.timestamp.clone(),
        })),
        None => Err((
            StatusCode::SERVICE_UNAVAILABLE,
            "First refresh not yet complete".into(),
        )),
    }
}

async fn handle_api_models(
    State(state): State<AppState>,
) -> Result<Json<ApiModelResponse>, (StatusCode, String)> {
    let latest = state.latest_status.read().await;
    match latest.as_ref() {
        Some(s) => Ok(Json(ApiModelResponse {
            loaded_model: s.loaded_model.clone(),
            available_models: s.available_models.clone(),
            total_count: s.available_models.len(),
        })),
        None => Err((
            StatusCode::SERVICE_UNAVAILABLE,
            "First refresh not yet complete".into(),
        )),
    }
}

/// Query parameters for the history endpoint.
#[derive(Debug, serde::Deserialize)]
struct HistoryQuery {
    range: Option<u64>,
}

/// Time-range presets (seconds).
const RANGE_15M: u64 = 15 * 60;
const RANGE_1H: u64 = 3600;
const RANGE_1D: u64 = 86400;
const RANGE_1W: u64 = 7 * 86400;

async fn handle_api_history(
    State(state): State<AppState>,
    Query(q): Query<HistoryQuery>,
) -> Result<Json<GpuHistoryResponse>, (StatusCode, String)> {
    let range_secs = q.range.unwrap_or(RANGE_1D);
    let records = state.database.fetch_history(range_secs);
    let peak = state.database.peak_vram();

    let data: Vec<GpuHistoryPoint> = records
        .into_iter()
        .map(|r| GpuHistoryPoint {
            timestamp: r.timestamp.timestamp_millis() as u64,
            memory_used_mib: r.memory_used_mib,
            temperature_c: r.temperature_c,
        })
        .collect();

    Ok(Json(GpuHistoryResponse {
        data,
        peak_vram_mib: peak,
    }))
}

// Handle CORS preflight for POST /api/clear-history.
async fn handle_clear_options() -> Result<Response<Body>, (StatusCode, String)> {
    Ok(Response::builder()
        .status(StatusCode::NO_CONTENT)
        .header(header::ACCESS_CONTROL_ALLOW_ORIGIN, "*")
        .header(header::ACCESS_CONTROL_ALLOW_METHODS, "POST, OPTIONS")
        .header(header::ACCESS_CONTROL_ALLOW_HEADERS, "Content-Type")
        .body(Body::empty())
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?)
}

async fn handle_clear_history(
    State(state): State<AppState>,
) -> Result<Json<serde_json::Value>, StatusCode> {
    state.database.clear_history();
    Ok(Json(serde_json::json!({ "cleared": true })))
}

// Re-export axum Response+Body so handlers compile.
use axum::{body::Body, response::Response};

// ── Router builder ───────────────────────────────────────

pub fn build_router(state: AppState) -> Router {
    Router::new()
        .route("/", get(handle_dashboard))
        .route("/api/status", get(handle_api_status))
        .route("/api/gpu", get(handle_api_gpu))
        .route("/api/models", get(handle_api_models))
        .route("/api/history", get(handle_api_history))
        .route("/api/clear-history", post(handle_clear_history).options(handle_clear_options))
        .with_state(state)
}

pub async fn bind_listener(config: &Config) -> Result<SocketAddr> {
    let addr: SocketAddr = format!("{}:{}", config.server_bind, config.server_port)
        .parse()
        .expect("invalid listen address");
    log_info!("Server will bind to {}", addr);
    Ok(addr)
}

// ── Embedded Dashboard HTML ────────────────

const DASHBOARD_HTML: &str = r#"<html><body></body></html>"#;

