/// Axum REST API server + embedded web dashboard.

use anyhow::Result;
use axum::{
    body::Body,
    extract::{Query, State},
    http::{header, Request, StatusCode},
    response::{Html, IntoResponse, Response},
    routing::{get, post},
    Router,
};
use std::{net::SocketAddr, sync::Arc, time::Duration};
use tokio::sync::RwLock;
use tracing::info as log_info;

use crate::config::Config;
use crate::db::Database;
use crate::gpu::try_query_gpu;
use crate::models::{ApiGpuResponse, ApiModelResponse, GpuHistoryPoint, GpuHistoryResponse, MonitorStatus};
use crate::ollama::OllamaClient;

fn now_ts() -> String {
    use std::time::SystemTime;
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .map_or("unknown".into(), |d| {
            let s = d.as_secs();
            format!("{} days {:02}:{:02}", s / 86400, (s % 3600) / 60, s % 60)
        })
}

#[derive(Clone)]
pub struct AppState {
    pub latest_status: Arc<RwLock<Option<MonitorStatus>>>,
    pub database: Database,
}

impl AppState {
    pub fn new(database: Database) -> Self {
        Self {
            latest_status: Arc::new(RwLock::new(None)),
            database,
        }
    }
}

// ── Background refresh loop ──────────────────────────────

pub async fn run_refresh_loop(config: &Config, state: AppState) {
    let client = OllamaClient::new(config.ollama_base_url());
    let interval = Duration::from_secs(config.refresh_interval_secs);

    loop {
        tokio::time::sleep(interval).await;

        let tags_resp = client.try_fetch_models().await;
        let available: Vec<String> = match &tags_resp {
            Some(tags) => tags.models.iter().map(|m| m.model_name.clone()).collect(),
            None => vec![],
        };
        let loaded_model = tags_resp
            .as_ref()
            .and_then(|t| t.models.first().cloned().map(|m| m.model_name));

        let gpu_metric = try_query_gpu(config.gpu_device_index);

        // Persist GPU snapshot to SQLite each cycle
        state
            .database
            .insert(gpu_metric.memory_used_mib, gpu_metric.temperature_c);

        let status = MonitorStatus {
            ollama_url: config.ollama_base_url(),
            ollama_reachable: tags_resp.is_some(),
            loaded_model,
            available_models: available.clone(),
            gpu: gpu_metric,
            timestamp: now_ts(),
        };

        let mut latest = state.latest_status.write().await;
        *latest = Some(status);
    }
}

// ── HTTP Handlers ────────────────────────────────────────

async fn handle_dashboard() -> Html<String> {
    Html(include_str!("../static/dashboard.html").to_owned())
}

async fn handle_api_status(
    State(state): State<AppState>,
) -> Result<axum::Json<MonitorStatus>, (StatusCode, String)> {
    let latest = state.latest_status.read().await;
    match latest.as_ref() {
        Some(s) => Ok(axum::Json(s.clone())),
        None => Err((
            StatusCode::SERVICE_UNAVAILABLE,
            "First refresh not yet complete".into(),
        )),
    }
}

async fn handle_api_gpu(
    State(state): State<AppState>,
) -> Result<axum::Json<ApiGpuResponse>, (StatusCode, String)> {
    let latest = state.latest_status.read().await;
    match latest.as_ref() {
        Some(s) => Ok(axum::Json(ApiGpuResponse {
            gpu: s.gpu.clone(),
            timestamp: s.timestamp.clone(),
        })),
        None => Err((
            StatusCode::SERVICE_UNAVAILABLE,
            "First refresh not yet complete".into(),
        )),
    }
}

async fn handle_api_models(
    State(state): State<AppState>,
) -> Result<axum::Json<ApiModelResponse>, (StatusCode, String)> {
    let latest = state.latest_status.read().await;
    match latest.as_ref() {
        Some(s) => Ok(axum::Json(ApiModelResponse {
            loaded_model: s.loaded_model.clone(),
            available_models: s.available_models.clone(),
            total_count: s.available_models.len(),
        })),
        None => Err((
            StatusCode::SERVICE_UNAVAILABLE,
            "First refresh not yet complete".into(),
        )),
    }
}

#[derive(Debug, serde::Deserialize)]
struct HistoryQuery {
    range: Option<u64>,
}

async fn handle_api_history(
    State(state): State<AppState>,
    Query(q): Query<HistoryQuery>,
) -> Result<axum::Json<GpuHistoryResponse>, (StatusCode, String)> {
    let range_secs = q.range.unwrap_or(86400); // default 1 day
    let records = state.database.fetch_history(range_secs);
    let peak = state.database.peak_vram();

    let data: Vec<GpuHistoryPoint> = records
        .into_iter()
        .map(|r| GpuHistoryPoint {
            timestamp: r.timestamp.timestamp_millis() as u64,
            memory_used_mib: r.memory_used_mib,
            temperature_c: r.temperature_c,
        })
        .collect();

    Ok(axum::Json(GpuHistoryResponse {
        data,
        peak_vram_mib: peak,
    }))
}

/// Handle CORS preflight for POST /api/clear-history (browser XHR needs OPTIONS).
async fn handle_clear_options() -> Result<impl IntoResponse, (StatusCode, String)> {
    Ok((
        StatusCode::NO_CONTENT,
        [
            (header::ACCESS_CONTROL_ALLOW_ORIGIN, "*"),
            (header::ACCESS_CONTROL_ALLOW_METHODS, "POST, OPTIONS"),
            (header::ACCESS_CONTROL_ALLOW_HEADERS, "Content-Type"),
        ],
    ))
}

async fn handle_clear_history(
    State(state): State<AppState>,
) -> Result<axum::Json<serde_json::Value>, StatusCode> {
    state.database.clear_history();
    Ok(axum::Json(serde_json::json!({ "cleared": true })))
}

// ── Router builder ───────────────────────────────────────

pub fn build_router(state: AppState) -> Router {
    Router::new()
        .route("/", get(handle_dashboard))
        .route("/api/status", get(handle_api_status))
        .route("/api/gpu", get(handle_api_gpu))
        .route("/api/models", get(handle_api_models))
        .route("/api/history", get(handle_api_history))
        .route(
            "/api/clear-history",
            post(handle_clear_history).options(handle_clear_options),
        )
        .fallback(|_req: Request<Body>| async {
            (
                StatusCode::NOT_FOUND,
                "The requested resource was not found",
            )
        })
        .with_state(state)
}

pub async fn bind_listener(config: &Config) -> Result<SocketAddr> {
    let addr: SocketAddr = format!("{}:{}", config.server_bind, config.server_port)
        .parse()
        .expect("invalid listen address");
    log_info!("Server will bind to {}", addr);
    Ok(addr)
}

/// SQLite-backed persistence for GPU metrics history.
use chrono::{DateTime, Utc};
use rusqlite::{Connection, Result as SqlResult};
use std::sync::Mutex;
use tracing::{debug, info, warn};

// ── Domain types ──────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct GpuRecord {
    pub timestamp: DateTime<Utc>,
    pub memory_used_mib: Option<u64>,
    pub temperature_c: Option<f64>,
}

// ── Database wrapper ──────────────────────────────────────────

pub struct Database {
    conn: Mutex<Connection>,
}

impl Database {
    /// Open (or create) the SQLite file at the given path, ensuring schema exists.
    pub fn new(path: &str) -> Self {
        let conn = Connection::open(path).unwrap_or_else(|e| {
            warn!("Failed to open sqlite db at {}: {}, using in-memory fallback", path, e);
            Connection::open_in_memory().expect("in-memory db should always work")
        });

        Self::ensure_schema(&conn).ok();
        Self {
            conn: Mutex::new(conn),
        }
    }

    fn ensure_schema(conn: &Connection) -> SqlResult<()> {
        conn.execute_batch(
            "
            CREATE TABLE IF NOT EXISTS gpu_history (
                id              INTEGER PRIMARY KEY AUTOINCREMENT,
                ts_epoch_ms     INTEGER NOT NULL,
                memory_used_mib INTEGER,
                temperature_c   REAL
            );
            CREATE INDEX IF NOT EXISTS idx_gpu_ts ON gpu_history(ts_epoch_ms);
            ",
        )?;
        Ok(())
    }

    /// Insert a single GPU snapshot.
    pub fn insert(&self, mem_used: Option<u64>, temp: Option<f64>) {
        let conn = self.conn.lock().unwrap();
        let epoch_ms = Utc::now().timestamp_millis();
        match conn.execute(
            "INSERT INTO gpu_history (ts_epoch_ms, memory_used_mib, temperature_c) VALUES (?, ?, ?)",
            (
                epoch_ms,
                mem_used.map(|v: u64| v as i64),
                temp,
            ),
        ) {
            Ok(_) => debug!("Inserted GPU record at {}", epoch_ms),
            Err(e) => warn!("Failed to insert GPU record: {}", e),
        }
    }

    /// Fetch records within the last `duration_secs` seconds.
    pub fn fetch_history(&self, duration_secs: u64) -> Vec<GpuRecord> {
        let conn = self.conn.lock().unwrap();
        let now_ms = Utc::now().timestamp_millis();
        let cutoff = now_ms - (duration_secs as i64 * 1000);

        let mut stmt = conn.prepare(
            "SELECT ts_epoch_ms, memory_used_mib, temperature_c \
             FROM gpu_history \
             WHERE ts_epoch_ms >= ? \
             ORDER BY ts_epoch_ms ASC"
        ).unwrap_or_else(|e| {
            warn!("Failed to prepare history query: {}", e);
            unreachable!()
        });

        let rows = stmt.query_map([cutoff], |row| {
            Ok(GpuRecord {
                timestamp: DateTime::from_timestamp_millis(row.get::<_, i64>(0)?).unwrap_or_default(),
                memory_used_mib: row.get::<_, Option<i64>>(1)?.map(|v| v as u64),
                temperature_c: row.get::<_, Option<f64>>(2).ok().flatten(),
            })
        }).unwrap_or_else(|e| {
            warn!("Failed to query history: {}", e);
            unreachable!()
        });

        rows.filter_map(|r| r.ok()).collect()
    }

    /// Return the all-time maximum VRAM usage (in MiB).
    pub fn peak_vram(&self) -> Option<u64> {
        let conn = self.conn.lock().unwrap();
        conn.query_row(
            "SELECT MAX(memory_used_mib) FROM gpu_history WHERE memory_used_mib IS NOT NULL",
            [],
            |row| row.get::<_, Option<i64>>(0),
        ).ok().flatten().map(|v| v as u64)
    }

    /// Delete all rows from the history table.
    pub fn clear_history(&self) {
        let conn = self.conn.lock().unwrap();
        match conn.execute("DELETE FROM gpu_history", []) {
            Ok(n) => info!("Cleared {} GPU history records", n),
            Err(e) => warn!("Failed to clear GPU history: {}", e),
        }
    }
}

