    /// Open (or create) the SQLite file at the given path, ensuring schema exists.
    pub fn new(path: &str) -> Self {
        let conn = Connection::open(path).unwrap_or_else(|e| {
            warn!("Failed to open sqlite db at {}: {}, using in-memory fallback", path, e);
            Connection::open_in_memory().expect("in-memory db should always work")
        });

        Self::ensure_schema(&conn).ok();
        Self {
            conn: Arc::new(Mutex::new(conn)),
        }
    }

    fn ensure_schema(conn: &Connection) -> SqlResult<()> {
        conn.execute_batch(
            "
            CREATE TABLE IF NOT EXISTS gpu_history (
                id              INTEGER PRIMARY KEY AUTOINCREMENT,
                ts_epoch_ms     INTEGER NOT NULL,
                memory_used_mib INTEGER,
                temperature_c   REAL
            );
            CREATE INDEX IF NOT EXISTS idx_gpu_ts ON gpu_history(ts_epoch_ms);
            ",
        )?;
        Ok(())
    }

    /// Insert a single GPU snapshot.
    pub fn insert(&self, mem_used: Option<u64>, temp: Option<f64>) {
        let conn = self.conn.lock().unwrap();
        let epoch_ms = Utc::now().timestamp_millis();
        match conn.execute(
            "INSERT INTO gpu_history (ts_epoch_ms, memory_used_mib, temperature_c) VALUES (?, ?, ?)",
            (epoch_ms, mem_used.map(|v: u64| v as i64), temp),
        ) {
            Ok(_) => debug!("Inserted GPU record at {}", epoch_ms),
            Err(e) => warn!("Failed to insert GPU record: {}", e),
        }
    }

    /// Fetch records within the last `duration_secs` seconds.
    pub fn fetch_history(&self, duration_secs: u64) -> Vec<GpuRecord> {
        let conn = self.conn.lock().unwrap();
        let now_ms = Utc::now().timestamp_millis();
        let cutoff = now_ms - (duration_secs as i64 * 1000);

        let mut stmt = conn.prepare(
            "SELECT ts_epoch_ms, memory_used_mib, temperature_c \
             FROM gpu_history \
             WHERE ts_epoch_ms >= ? \
             ORDER BY ts_epoch_ms ASC"
        ).unwrap_or_else(|e| {
            warn!("Failed to prepare history query: {}", e);
            unreachable!()
        });

        let rows = stmt.query_map([cutoff], |row| {
            Ok(GpuRecord {
                timestamp: DateTime::from_timestamp_millis(row.get::<_, i64>(0)?).unwrap_or_default(),
                memory_used_mib: row.get::<_, Option<i64>>(1)?.map(|v| v as u64),
                temperature_c: row.get::<_, Option<f64>>(2).ok().flatten(),
            })
        }).unwrap_or_else(|e| {
            warn!("Failed to query history: {}", e);
            unreachable!()
        });

        rows.filter_map(|r| r.ok()).collect()
    }

    /// Return the all-time maximum VRAM usage (in MiB).
    pub fn peak_vram(&self) -> Option<u64> {
        let conn = self.conn.lock().unwrap();
        conn.query_row(
            "SELECT MAX(memory_used_mib) FROM gpu_history WHERE memory_used_mib IS NOT NULL",
            [],
            |row| row.get::<_, Option<i64>>(0),
        ).ok().flatten().map(|v| v as u64)
    }

    /// Delete all rows from the history table.
    pub fn clear_history(&self) {
        let conn = self.conn.lock().unwrap();
        match conn.execute("DELETE FROM gpu_history", []) {
            Ok(n) => info!("Cleared {} GPU history records", n),
            Err(e) => warn!("Failed to clear GPU history: {}", e),
        }
    }
}

